  data = $tescjson${"slug": "teaching-elementary-science", "title": "Teaching Elementary Science", "description": "This course is designed for future elementary teachers who need to plan safe, equitable, standards-aligned, inquiry-rich science learning for K-6 classrooms.", "topics": [{"id": "e416d09a-e5b4-4f36-b3b0-e6f4592a57c4", "type": "topic", "title": "Foundations of Elementary Science Teaching and Science Identity", "description": "Introduces elementary science as sensemaking, curiosity, evidence, identity-building, and equitable participation.", "children": [{"id": "2dcef03e-a6ca-4574-8043-76be11100acd", "type": "subtopic", "title": "Science as Sensemaking", "children": [{"id": "cff345d5-0810-4f48-a6a5-9579788f8082", "type": "concept", "title": "phenomenon"}, {"id": "52444859-19a4-4a13-bf33-9426999e0069", "type": "concept", "title": "sensemaking"}, {"id": "4ad66d07-8a11-45fe-a999-b92335ac9875", "type": "concept", "title": "student question"}, {"id": "da6507a8-30f0-4180-83cc-2b724b4b25f3", "type": "concept", "title": "evidence"}, {"id": "7970d3eb-0134-4d4f-8595-a21be35af226", "type": "concept", "title": "explanation"}, {"id": "27154de9-0eef-4012-8d79-0ca8c67e01d7", "type": "concept", "title": "model"}, {"id": "eb3a9695-4d9a-41bf-910d-886e45898bc3", "type": "concept", "title": "investigation"}, {"id": "fd0dc162-624f-4206-a386-9815c8a2b393", "type": "concept", "title": "curiosity"}, {"id": "c3d314c1-dcde-479f-9915-87e42b5e6930", "type": "concept", "title": "wonder routine"}], "description": "Students learn to frame science as explaining the world with evidence rather than memorizing facts."}, {"id": "46bc077e-47da-4f46-9c3d-9963c1f84518", "type": "subtopic", "title": "Children's Ideas About Science", "children": [{"id": "c2308f2f-49f1-46a0-93d1-7ea101697a69", "type": "concept", "title": "prior knowledge"}, {"id": "871b59a3-08b0-475c-87bb-36d164876209", "type": "concept", "title": "preconception"}, {"id": "ef9d5419-5e82-420b-9f06-49bf36a77555", "type": "concept",